import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';

const Header = ({ showUserMenu = true }) => {
  const { user, logout, darkMode, toggleDarkMode } = useAuth();
  const [language, setLanguage] = useState('fr');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isLangDropdownOpen, setIsLangDropdownOpen] = useState(false);

  const languages = [
    { code: 'fr', name: 'Français', flag: '🇫🇷' },
    { code: 'mg', name: 'Malagasy', flag: '🇲🇬' },
    { code: 'en', name: 'English', flag: '🇬🇧' },
  ];

  const handleLanguageChange = (langCode) => {
    setLanguage(langCode);
    setIsLangDropdownOpen(false);
  };

  return (
    <header className="sticky top-0 z-50 bg-white dark:bg-neutral-900 shadow-md">
      <div className="container mx-auto px-4 py-3">
        <div className="flex items-center justify-between">
          {/* Logo */}
          <div className="flex items-center space-x-2">
            <div className="w-10 h-10 bg-gradient-to-r from-primary-500 to-accent-500 rounded-lg"></div>
            <span className="text-xl font-bold text-neutral-800 dark:text-white">
              MyApp
            </span>
          </div>

          {/* Menu de navigation */}
          <nav className="hidden md:flex items-center space-x-6">
            <a href="/" className="text-neutral-600 dark:text-neutral-300 hover:text-primary-500 dark:hover:text-primary-400 transition-colors">
              Accueil
            </a>
            <a href="/dashboard" className="text-neutral-600 dark:text-neutral-300 hover:text-primary-500 dark:hover:text-primary-400 transition-colors">
              Dashboard
            </a>
            <a href="#" className="text-neutral-600 dark:text-neutral-300 hover:text-primary-500 dark:hover:text-primary-400 transition-colors">
              Services
            </a>
            <a href="#" className="text-neutral-600 dark:text-neutral-300 hover:text-primary-500 dark:hover:text-primary-400 transition-colors">
              Contact
            </a>
          </nav>

          {/* Actions */}
          <div className="flex items-center space-x-4">
            {/* Bouton Mode Sombre/Clair */}
            <button
              onClick={toggleDarkMode}
              className="p-2 rounded-full bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors"
              aria-label={darkMode ? 'Passer en mode clair' : 'Passer en mode sombre'}
            >
              {darkMode ? '☀️' : '🌙'}
            </button>

            {/* Sélecteur de langue */}
            <div className="relative">
              <button
                onClick={() => setIsLangDropdownOpen(!isLangDropdownOpen)}
                className="flex items-center space-x-2 px-3 py-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors"
              >
                <span>{languages.find(l => l.code === language)?.flag}</span>
                <span className="text-neutral-700 dark:text-neutral-200">
                  {language.toUpperCase()}
                </span>
                <span>▼</span>
              </button>

              {isLangDropdownOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-neutral-800 rounded-lg shadow-lg py-2 z-50">
                  {languages.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => handleLanguageChange(lang.code)}
                      className="flex items-center space-x-3 w-full px-4 py-2 text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                    >
                      <span>{lang.flag}</span>
                      <span className="text-neutral-700 dark:text-neutral-200">
                        {lang.name}
                      </span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Menu utilisateur */}
            {showUserMenu && user && (
              <div className="relative">
                <button
                  onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                  className="flex items-center space-x-2"
                >
                  <div className="w-10 h-10 rounded-full bg-gradient-to-r from-primary-400 to-secondary-400 flex items-center justify-center text-white font-bold">
                    {user.name.charAt(0).toUpperCase()}
                  </div>
                  <span className="hidden md:inline text-neutral-700 dark:text-neutral-200">
                    {user.name}
                  </span>
                </button>

                {isDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-neutral-800 rounded-lg shadow-lg py-2 z-50">
                    <div className="px-4 py-2 border-b border-neutral-200 dark:border-neutral-700">
                      <p className="font-medium text-neutral-800 dark:text-white">{user.name}</p>
                      <p className="text-sm text-neutral-500 dark:text-neutral-400">{user.email}</p>
                    </div>
                    <a
                      href="/dashboard"
                      className="block px-4 py-2 text-neutral-700 dark:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                    >
                      Mon profil
                    </a>
                    <a
                      href="#"
                      className="block px-4 py-2 text-neutral-700 dark:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                    >
                      Paramètres
                    </a>
                    <button
                      onClick={logout}
                      className="block w-full text-left px-4 py-2 text-red-600 hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                    >
                      Déconnexion
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Menu mobile */}
        <div className="md:hidden mt-3">
          <div className="flex space-x-4 overflow-x-auto">
            <a href="/" className="text-sm text-neutral-600 dark:text-neutral-300 hover:text-primary-500">
              Accueil
            </a>
            <a href="/dashboard" className="text-sm text-neutral-600 dark:text-neutral-300 hover:text-primary-500">
              Dashboard
            </a>
            <a href="#" className="text-sm text-neutral-600 dark:text-neutral-300 hover:text-primary-500">
              Services
            </a>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;
